<?php
declare(strict_types=1);

use TF\Db;
use TF\Migrator;

// #265: only replace the exact previous default text. Preserve locally edited
// built-ins and all user exercises; do not re-sync equipment, names or history.
return static function (Db $db, Migrator $m): void {
    $updates = [
        'dumbbell-bench-press' => ['Start with the dumbbells stacked over your shoulders. Lower until your elbows dip just below the bench, about 45 degrees from your ribs, then press back together without clanking the bells.', 'Lie on a flat bench with feet planted and dumbbells above your chest. Lower beside your chest with wrists above elbows and upper arms angled away from your ribs, then press back up without bouncing.'],
        'chest-dip' => ['Lean your torso forward and let your elbows drift out a little. Lower until your upper arms are about level with the bars, then drive up without shrugging.', 'Support yourself on the dip bars with arms straight and lean forward slightly. Bend your elbows to lower until your upper arms are about parallel to the floor, or stop sooner if your shoulders feel strained, then press up.'],
        'incline-dumbbell-press' => ['Set the bench around 30 degrees. Press the dumbbells up over your collarbones, then lower them wide and deep while keeping your wrists stacked over your elbows.', 'Lie on a bench set around 30 degrees with feet planted and dumbbells above your upper chest. Lower beside your chest with wrists above elbows, then press up without lifting your shoulders off the bench.'],
        'feet-elevated-push-up' => ['Put your feet on a stable exercise step, box or bench and your hands on the floor. Keep your body rigid, lower your face toward the floor between your hands, and press back up.', 'Place your feet on a stable step or bench and hands slightly wider than your shoulders on the floor. Keep your body straight as you bend your elbows to lower your chest toward the floor, then press up.'],
        'band-fly' => ['Anchor the band behind you at chest height. Step forward until there is tension and bring your hands together in front of you, holding the squeeze for a beat.', 'Secure the band behind you at chest height and step forward until it is taut. Keep a slight bend in your elbows as you bring your hands together in front of your chest, then slowly open your arms again.'],
        'overhead-press' => ['Grip just outside your shoulders with the bar resting on your upper chest. Brace your abs and glutes, press straight up, and move your head through once the bar clears it.', 'Hold the bar at your upper chest with hands just outside shoulder width. Tighten your stomach and buttocks, move your head back to let the bar pass, and press overhead without leaning back; lower to your upper chest.'],
        'seated-dumbbell-press' => ['Set the bench nearly upright. Start with the dumbbells at ear height, elbows slightly in front of your body, and press until your arms are straight overhead.', 'Sit against a nearly upright bench with feet planted and dumbbells beside your shoulders, palms forward. Press overhead without arching your back, then lower slowly to the starting position.'],
        'kettlebell-press' => ['Rack the kettlebell against your forearm with your wrist straight. Press up while rotating your palm forward, finishing with your arm beside your ear.', 'Stand holding a kettlebell at one shoulder with the bell against your forearm and wrist straight. Press overhead without leaning back, then lower to your shoulder; repeat on the other side.'],
        'cable-lateral-raise' => ['Stand side-on to a low pulley and hold the handle in your far hand. Raise your arm out to the side to shoulder height and resist the cable on the way down.', 'Stand side-on to a low pulley and hold the handle in the hand farther from the machine. With a slight elbow bend, raise that arm sideways to shoulder height, then lower slowly; repeat on the other side.'],
        'cable-pushdown' => ['Pin your elbows to your sides and hinge forward slightly. Push the handle down until your arms are straight, then let your forearms rise to just past level.', 'Face a high pulley and hold the handle with elbows beside your ribs. Keep your upper arms still as you straighten your elbows to push down, then slowly bend them to return.'],
        'skull-crusher' => ['Lie back holding the bar over your forehead with your upper arms tilted slightly toward your head. Bend only at the elbows to lower the bar behind your hairline, then extend.', 'Lie on a bench holding the EZ bar above your chest with a close overhand grip. Keep your upper arms steady as you bend your elbows to lower the bar just behind your head, then straighten your arms.'],
        'close-grip-bench-press' => ['Grip the bar at shoulder width. Tuck your elbows close as you lower to your lower chest, and press up by straightening your arms.', 'Lie on the bench with feet planted and hold the bar above your chest using a shoulder-width overhand grip. Lower to your lower chest with elbows close to your sides, then press up without lifting your shoulders.'],
        'diamond-push-up' => ['Place your hands close together under your chest. Keep your elbows brushing your ribs as you lower, then press up to full lockout.', 'Start in a push-up position with hands close together beneath your chest and body straight. Bend your elbows back close to your sides to lower your chest, then press up without letting your hips sag.'],
        'assisted-pull-up' => ['Pick enough assistance to reach your rep target. Pull your elbows down and back, pause with your chin over the handles, and lower slowly. Less assistance is harder.', 'Grip the overhead handles and place your knees or feet on the assistance platform as the machine directs. Pull until your chin clears the handles without swinging, then lower slowly until your arms straighten; more assistance makes it easier.'],
        'band-pulldown' => ['Anchor the band overhead and kneel under it. Pull your hands down to your shoulders by driving your elbows toward your hips.', 'Secure the band overhead and kneel facing the anchor with arms reaching up. Pull your hands toward your shoulders with elbows moving down beside your ribs, then slowly extend your arms again.'],
        'one-arm-dumbbell-row' => ['Brace one hand and knee on the bench. Pull the dumbbell toward your hip, keeping your shoulders square to the floor, and stretch your arm fully at the bottom.', 'Support one hand and knee on a bench, with the other foot on the floor and a dumbbell hanging from your free hand. Pull toward your hip without twisting your torso, then lower until your arm straightens; repeat on the other side.'],
        'standing-cable-row' => ['Set the pulley at waist height and stand in a staggered stance. Pull the handle to your side, elbow close to your body, without twisting your torso.', 'Set a pulley at waist height and face it in a staggered stance, holding the handle in one hand. Pull to your side without twisting or leaning back, then slowly straighten your arm; repeat on the other side.'],
        'inverted-row' => ['Set a bar at hip height in the rack and hang underneath it with heels on the floor. Keep your body straight and pull your chest to the bar.', 'Secure a bar in a rack so it cannot roll or lift out, then lie underneath and grip it slightly wider than your shoulders. With heels on the floor and body straight, pull your chest toward the bar, then lower until your arms straighten.'],
        'kettlebell-row' => ['Hinge forward with a flat back and one hand braced on your thigh. Row the kettlebell to your hip and lower it with control.', 'Stagger your feet and bend forward at the hips, supporting your free hand on your front thigh. Pull the kettlebell toward your hip without twisting, then lower slowly; repeat on the other side.'],
        'band-row' => ['Anchor the band at chest height. Step back into tension and pull your hands to your ribs, squeezing your shoulder blades together.', 'Secure the band at chest height and hold its ends with arms reaching forward. Pull your hands toward your ribs without leaning back, then slowly straighten your arms while keeping tension on the band.'],
        'bent-over-reverse-fly' => ['Hinge forward with a flat back and let the dumbbells hang. Raise them out to the sides with a slight elbow bend, leading with your pinkies.', 'Bend forward at your hips with knees slightly bent, back steady, and dumbbells hanging below your chest. With elbows slightly bent, raise your arms out to the sides to about shoulder level, then lower slowly.'],
        'ez-bar-curl' => ['Stand tall with elbows at your sides. Curl the bar to shoulder height without swinging, then lower until your arms are fully straight.', 'Stand holding the angled parts of the EZ bar with palms facing up and elbows beside your ribs. Curl toward your shoulders without swinging, then slowly straighten your elbows.'],
        'dumbbell-curl' => ['Start with your palm facing your thigh and turn it up as you curl. Do both sides. Keep your upper arms still and lower all the way down.', 'Stand with one dumbbell beside your thigh, palm facing inward. Keep your upper arm beside your ribs as you curl toward your shoulder and turn your palm upward, then lower slowly; repeat on the other side.'],
        'hammer-curl' => ['Keep your palm facing inward throughout. Do both sides. Curl to shoulder height with elbows fixed and lower under control.', 'Stand with one dumbbell beside your thigh, palm facing inward. Keep that grip and your upper arm still as you curl toward your shoulder, then lower slowly; repeat on the other side.'],
        'incline-dumbbell-curl' => ['Lie back on a 45 to 60 degree incline and let your working arm hang behind your body. Do both sides. Curl without letting your elbows drift forward.', 'Sit back against a bench set to 45–60 degrees with one dumbbell hanging at your side, palm forward. Keep your upper arm still as you curl toward your shoulder, then lower slowly; repeat on the other side.'],
        'back-squat' => ['Rest the bar on your upper back and take a breath into your belly. Sit down between your hips with knees tracking over your toes until your thighs reach parallel, then stand by driving the floor away.', 'Set the bar across your upper back, not your neck, and stand with feet about shoulder-width apart. Tighten your stomach and bend your hips and knees to squat as low as you can control with heels down and knees following your toes, then stand.'],
        'leg-press' => ['Place your feet shoulder-width in the middle of the platform. Lower until your knees pass 90 degrees while your lower back stays on the pad, then press without locking your knees hard.', 'Sit with your back and hips against the pad and feet shoulder-width apart on the platform. Lower only as far as you can keep your heels planted and hips on the pad, then press away without snapping your knees straight.'],
        'goblet-squat' => ['Hold one dumbbell against your chest. Keep your torso upright and squat between your knees until your elbows reach the inside of your thighs.', 'Stand with feet about shoulder-width apart, holding one dumbbell upright against your chest. Bend your hips and knees to squat as low as you can control with heels down and knees following your toes, then stand.'],
        'front-squat' => ['Rack the bar on the front of your shoulders with elbows high. Stay upright as you squat to depth and drive your elbows up as you stand.', 'Rest the bar across the front of your shoulders with elbows pointing forward and feet about shoulder-width apart. Keep your chest lifted as you bend your hips and knees into a controlled squat, then stand without letting your elbows drop.'],
        'smith-squat' => ['Stand with your feet slightly ahead of the bar. Unhook, squat until your thighs are parallel, and stand up without bouncing off the bottom.', 'Position the bar across your upper back, set the safety stops, and place your feet slightly forward. Unhook the bar and squat to a controlled depth with heels planted, then stand and rehook the bar when finished.'],
        'bodyweight-squat' => ['Feet shoulder-width, arms out front for balance. Sit down and back until your thighs are at least parallel and stand up tall. Slow the lowering to make it harder.', 'Stand with feet about shoulder-width apart and arms forward for balance. Bend your hips and knees to squat as low as you can control with heels planted and knees following your toes, then stand tall.'],
        'deadlift' => ['Set the bar over mid-foot, grip it, and bring your shins in. Flatten your back, pull the slack out of the bar, and stand up by pushing the floor away. Lower it along your legs.', 'Stand with the bar over the middle of your feet and grip it just outside your legs. Tighten your stomach, keep your back steady, and push through your feet to stand with the bar close to your legs; bend your hips and knees to lower it to the floor.'],
        'dumbbell-rdl' => ['Hold the dumbbells in front of your thighs. Hinge back with a flat spine until they reach mid-shin, then drive your hips forward to stand.', 'Stand with dumbbells in front of your thighs and knees slightly bent. Push your hips back, keeping the weights close to your legs, until your hamstrings stretch without rounding your back, then stand tall.'],
        'kettlebell-swing' => ['Hike the bell back between your legs and snap your hips forward so it floats to chest height. Your arms guide it; your hips do the work.', 'Start with the kettlebell on the floor just ahead of you, then bend at your hips and pull it back between your legs. Drive your hips forward to swing it to about chest height with relaxed arms, then bend at your hips as it swings back; do not lift it with your shoulders.'],
        'dumbbell-reverse-lunge' => ['Step back far enough that both knees reach about 90 degrees. Keep your weight on the front foot and push through it to return. Count reps per side.', 'Stand holding one dumbbell at your side and step one foot back. Bend both knees to lower your back knee toward the floor, then push through your front foot to stand; repeat on the other side.'],
        'bulgarian-split-squat' => ['Hold a dumbbell in each hand. Rest your back foot on the bench and hop your front foot forward. Drop your back knee straight down, lean slightly forward, and stand through your front heel. Count reps per side.', 'Hold a dumbbell in each hand with your back foot resting on a bench and front foot far enough forward to balance. Bend both knees to lower your back knee toward the floor, then push through your whole front foot to rise; repeat on the other side.'],
        'barbell-hip-thrust' => ['Sit with your upper back against the bench and the bar over your hip crease. Drive through your heels until your torso is level, tuck your chin, and pause at the top.', 'Sit on the floor with your upper back against a stable bench, knees bent, and a padded bar across your hips. Push through your feet to lift your hips until shoulders, hips, and knees line up without arching your lower back, then lower slowly.'],
        'leg-curl' => ['Line your knees up with the machine pivot. Curl the pad as far as it goes without lifting your hips, then let it back out over two to three seconds.', 'Adjust the machine so your knees line up with its pivot and the moving pad sits just above your heels. Bend your knees to curl the pad toward your buttocks without lifting your hips, then slowly straighten your legs.'],
        'machine-calf-raise' => ['Stand on the balls of your feet with heels hanging off. Lower into a deep stretch, pause, and rise as high as you can.', 'Position your shoulders under the pads and the balls of your feet on the platform with heels free to move. Rise onto the balls of your feet, then lower your heels into a comfortable stretch without bouncing.'],
        'leg-press-calf-raise' => ['Put the balls of your feet on the bottom edge of the platform with legs nearly straight. Push through your toes and let your heels drop under control. Keep the safeties engaged.', 'Use only a leg press designed for calf raises, with its safety stops set. Place the balls of your feet securely on the platform edge and keep your knees nearly straight; raise and lower your heels slowly without letting your feet slip.'],
        'hanging-leg-raise' => ['Hang from the bar without swinging. Curl your pelvis up as you raise your knees or straight legs, and lower them slowly.', 'Hang from a secure bar with legs straight and body still. Raise your legs in front of you while gently curling your hips upward, then lower without swinging.'],
        'dead-bug' => ['Lie on your back with arms up and knees over hips. Reach one arm and the opposite leg toward the floor while your lower back stays flat. Count reps per side.', 'Lie on your back with arms pointing up, knees bent to 90 degrees, and knees above your hips. Slowly reach one arm overhead and extend the opposite leg while keeping your lower back against the floor, then return and switch sides.'],
        'rowing-machine' => ['Push with your legs first, then lean back slightly and pull the handle to your lower ribs. Return in the reverse order: arms, body, then legs.', 'Sit with feet secured, knees bent, arms straight, and back steady. Push with your legs, lean back slightly, then pull the handle to your lower ribs; return by straightening your arms, leaning forward, then bending your knees.'],
        'leg-swings' => ['Hold a wall or rack for balance and swing one straight leg forward and back, a little higher each time. Keep your torso tall. Then switch legs.', 'Hold a wall or rack for balance and swing one leg forward and back with a slight knee bend. Keep your torso still and use a comfortable range rather than forcing the swing; repeat on the other side.'],
        'walking-knee-hug' => ['Step forward and pull one knee toward your chest with both hands, rising onto the toes of your standing foot. Release, step, and repeat. Then switch legs.', 'Stand tall and bring one knee toward your chest, gently holding it with both hands. Release, step forward, and repeat with the other leg, keeping your balance throughout.'],
        'overhead-triceps-stretch' => ['Reach one arm overhead and bend the elbow so your hand drops behind your head. Gently press the elbow back with your other hand. Then switch sides.', 'Reach one arm overhead and bend its elbow so your hand rests behind your upper back. Use your other hand to gently guide the elbow back until you feel a mild stretch, then hold without bouncing; switch sides.'],
        'cobra-stretch' => ['Lie face down with hands under your shoulders. Press up gently, keeping your hips on the floor, until you feel a stretch through your stomach.', 'Lie face down with palms beside your chest and elbows close to your sides. Gently lift your chest using your back and only as much hand pressure as needed, keeping hips down and stopping before your lower back feels compressed.'],
        'dumbbell-front-raise' => ['Hold the dumbbell in front of your thigh. Raise it with a straight arm to shoulder height without leaning back, and lower slowly. Do both sides.', 'Stand holding one dumbbell in front of your thigh, palm facing you. With a slight elbow bend, raise it forward to shoulder height without leaning back, then lower slowly; repeat on the other side.'],
        'bodyweight-bulgarian-split-squat' => ['Rest your back foot on the bench and step your front foot forward. Lower your back knee straight down and stand through your front heel. Hold weights to make it harder. Count reps per side.', 'Rest your back foot on a bench and place your front foot far enough forward to balance. Bend both knees to lower your back knee toward the floor, then push through your whole front foot to rise; repeat on the other side.'],
        'incline-dumbbell-fly' => ['On a bench set to about 30 degrees, open the dumbbells out in a wide arc with soft elbows until your chest stretches, then bring them back together over your upper chest.', 'Lie on a bench set around 30 degrees with dumbbells above your upper chest. Keep a slight bend in your elbows as you open your arms to a comfortable chest stretch, then bring the weights back together along the same arc.'],
        'zottman-curl' => ['Curl the dumbbell up with your palm facing up, turn your palm down at the top, and lower slowly with the overhand grip. Do both sides.', 'Stand holding one dumbbell at your side with palm forward and upper arm still. Curl toward your shoulder, turn your palm down at the top, and lower slowly; turn your palm forward again and repeat, then switch sides.'],
        'shotgun-row' => ['Hold a low cable handle in one hand with your palm facing up. Row it to your side while turning your palm toward you, and reach forward to stretch. Count reps per side.', 'Face a low pulley in a staggered stance with one arm reaching forward, palm down. Pull the handle toward your side while turning your palm upward, then slowly reach forward and reverse the turn; repeat on the other side.'],
        'cable-rope-overhead-triceps-extension' => ['Face away from the pulley holding the rope behind your head. Keep your elbows pointing forward and straighten your arms overhead, then let the rope back slowly.', 'Attach a rope to a low pulley and face away, holding the ends behind your head with elbows pointing upward. Keep your upper arms still as you straighten your elbows overhead, then slowly bend them to return.'],
        'plate-loaded-leg-press' => ['Sit in the sled with feet shoulder-width on the platform. Release the safeties, lower until your knees pass 90 degrees while your lower back stays down, and press back up.', 'Sit with your back and hips against the pad and feet shoulder-width apart on the platform. Set the safety stops and release the sled, then lower only while your heels and hips stay planted; press up without snapping your knees straight.'],
        'palms-up-dumbbell-wrist-curl' => ['Rest your forearm on your thigh or the bench with your palm up and wrist past the edge. Curl the dumbbell up with your wrist, then lower it into your fingers. Do both sides.', 'Rest your forearm on your thigh or a bench, palm up and wrist just beyond the edge. Keep your forearm still as you bend your wrist to raise the dumbbell, then lower slowly; repeat on the other side.'],
        'biceps-curl-to-shoulder-press' => ['Curl the dumbbells to your shoulders, then press them overhead. Lower them back to your shoulders and uncurl to your sides.', 'Stand with dumbbells at your sides, palms forward. Curl to your shoulders, turn your palms forward, and press overhead without leaning back; lower to your shoulders, then straighten your elbows to return to your sides.'],
        'russian-twist' => ['Sit with knees bent and lean back until your abs engage. Turn your torso from side to side, touching the floor or a weight beside each hip.', 'Sit with knees bent, heels on the floor, and torso leaning back slightly. Turn your chest and hands together from side to side while keeping your hips still; hold a weight only if you can control the movement.'],
        'incline-hammer-curl' => ['Lie back on an incline bench with your arm hanging, palm facing in. Curl without letting your elbow move forward and lower to a full stretch. Do both sides.', 'Sit back against an incline bench with one dumbbell hanging at your side, palm facing inward. Keep your upper arm still as you curl toward your shoulder and lower slowly; repeat on the other side.'],
        'hip-abductor-machine' => ['Sit with the pads on the outside of your knees. Push your knees apart as far as you can, pause, and bring them back slowly.', 'Sit against the backrest with pads against the outside of your knees. Move your knees apart through a comfortable range without rocking your torso, then bring them back slowly.'],
        'seated-back-extension-machine' => ['Sit with the pad across your upper back. Push back until your torso is upright or slightly past, then return slowly with control.', 'Adjust the machine so the back pad supports your upper back and secure your feet. Keeping your hips against the seat, push back to a comfortable upright position, then return slowly without forcing your lower back into an arch.'],
        'single-arm-lat-pulldown' => ['Use a single handle on the pulldown. Pull it down to your shoulder by driving your elbow toward your hip, then let it rise fully. Count reps per side.', 'Sit with thighs secured under the pad and hold a single overhead handle. Pull toward your shoulder with your elbow moving down beside your ribs, then slowly extend your arm; repeat on the other side.'],
        'no-money-curl' => ['Hold light dumbbells with elbows bent at 90 degrees and tucked at your sides, palms up. Rotate your forearms outward without moving your elbows, then return.', 'Stand holding light dumbbells with palms up, elbows bent to 90 degrees and tucked beside your ribs. Keep your upper arms still as you rotate your forearms outward, then return; this is a rotation, not an elbow curl.'],
        'alternating-dumbbell-bench-press' => ['Press both dumbbells up, then lower and press one at a time while the other stays locked out overhead. Keep your hips still.', 'Lie on a flat bench with feet planted and both dumbbells above your chest. Lower and press one dumbbell while the other stays overhead, then alternate arms without twisting your torso.'],
        'lateral-to-front-raise' => ['Raise the dumbbells out to the sides to shoulder height, sweep them to the front, lower them, then reverse the path on the next rep.', 'Stand with dumbbells at your sides and elbows slightly bent. Raise them sideways to shoulder height, move them together in front of you, and lower; on the next rep raise forward, move sideways, and lower.'],
        'home-gym-rope-pushdown' => ['Pin your elbows to your sides holding the rope. Push down and spread the ends at the bottom, then let your forearms rise slowly.', 'Face the high pulley holding the rope with elbows beside your ribs. Keep your upper arms still as you straighten your elbows and separate the rope ends, then slowly bend your elbows to return.'],
        'kneeling-squat' => ['Kneel on a pad with a weight held at your chest or on your back. Sit your hips back to your heels, then drive them forward to tall kneeling.', 'Kneel on a padded surface with your torso upright. Bend at your hips to sit back toward your heels, then squeeze your buttocks to return to tall kneeling without arching your lower back.'],
        'superman' => ['Lie face down with arms overhead. Lift your arms, chest and legs off the floor together, hold briefly, and lower.', 'Lie face down with arms reaching overhead and neck in line with your spine. Gently lift your arms, chest, and legs a small distance without throwing your head back, then lower slowly.'],
        'smith-machine-shoulder-press' => ['Sit upright on a bench under the bar. Press it overhead from chin height and lower it back to your upper chest.', 'Place a nearly upright bench under the Smith bar, set the safety stops, and grip the bar slightly wider than your shoulders. Unhook and press from your upper chest to overhead without arching off the backrest, then lower slowly.'],
        'cuban-rotation' => ['Hold light dumbbells with elbows out at shoulder height. Rotate your forearms up until your hands point to the ceiling, then lower back down slowly.', 'Stand with light dumbbells, upper arms out at shoulder height, elbows bent to 90 degrees, and forearms pointing down. Keep your upper arms still while rotating your forearms upward, then lower slowly through a comfortable range.'],
        'barbell-pause-curl' => ['Curl the bar halfway up and hold for two seconds, then finish the curl. Lower slowly all the way down.', 'Stand holding the bar with a shoulder-width palms-up grip and elbows beside your ribs. Curl halfway and pause for two seconds before finishing toward your shoulders, then lower slowly without swinging.'],
        'cable-crossover-pulldown' => ['Kneel between two high pulleys holding the opposite handles. Pull your elbows down to your sides, then let your arms rise and cross overhead.', 'Kneel between two high pulleys and hold the left handle in your right hand and the right handle in your left. Pull your elbows down beside your ribs, then slowly reach upward along the crossed cable paths.'],
        'rotary-torso-machine' => ['Sit with your chest against the pad and feet locked. Turn your torso to one side against the resistance, then return slowly. Count reps per side.', 'Adjust the seat, pads, and foot supports to the machine instructions. Keep the supported part of your body still as you rotate the moving section through a comfortable range, then return slowly; repeat on the other side.'],
        'ez-bar-pjr-pullover' => ['Lie on the bench holding the EZ bar over your chest. Lower it toward your chin by bending your elbows and letting them drift back, then press it back over your chest.', 'Lie on a bench holding the EZ bar above your chest with a close grip. Bend your elbows and let your upper arms move back to lower the bar behind your head, then reverse the motion to return above your chest.'],
        'incline-ez-bar-curl' => ['Lie back on an incline bench with your arms hanging. Curl the bar up without letting your elbows move forward, then lower to a full stretch.', 'Sit back against an incline bench holding the EZ bar with palms up and arms hanging beside your torso. Curl toward your shoulders without moving your upper arms, then lower slowly; use a bench position that leaves the bar clear of your thighs.'],
        'smith-machine-behind-the-back-shrug' => ['Stand in front of the bar and hold it behind you. Shrug your shoulders up and slightly back, pause, and lower all the way.', 'Stand just in front of the Smith bar and hold it behind your thighs with straight arms. Unhook and lift your shoulders straight upward without rolling them, then lower slowly and rehook after the set.'],
    ];
    foreach ($updates as $slug => [$old, $new]) {
        foreach ($db->all('SELECT id, cues FROM exercises WHERE slug=? AND user_id IS NULL', [$slug]) as $row) {
            // Compare in PHP too: MySQL's default collation is case-insensitive.
            if ($row['cues'] === $old) {
                $db->run('UPDATE exercises SET cues=? WHERE id=? AND user_id IS NULL AND cues=?', [$new, $row['id'], $old]);
            }
        }
    }
};
